5	namespace App\Console\Commands;
6	
7	use App\Models\Fabric;
8	use App\Models\Product;
9	use Illuminate\Console\Command;
10	
11	/**
12	 * Associa la relazione prodotto ↔ tessuto (`fabric_product`) per Outdoor.
13	 *
14	 * A differenza di Interior — dove `app:import-fabrics-rel-product` legge una
15	 * matrice che dice quali *tipologie* di tessuto sono disponibili per ogni
16	 * prodotto — Outdoor **non ha una matrice**: per decisione del cliente,
17	 * qualunque tessuto Outdoor può rivestire qualunque prodotto Outdoor. La
18	 * relazione è quindi il prodotto cartesiano dei due insiemi, non un import da
19	 * file.
20	 *
21	 * Destinazione risolta via `Category1` (slug `outdoor`): sul `Fabric` tramite
22	 * `FabricCategory.category_1_id`, sul `Product` tramite `Category2.category_1_id`
23	 * (un prodotto non ha la destinazione in colonna propria, la eredita dalla
24	 * collezione).
25	 *
26	 * Idempotente: `sync()` per prodotto, come il comando Interior — un rilancio
27	 * dopo l'arrivo di nuovi prodotti o tessuti Outdoor riallinea tutto senza
28	 * lasciare residui. Va rilanciato ogni volta che cambia l'uno o l'altro
29	 * insieme (nuovo import prodotti Outdoor, nuovo import tessuti Outdoor).
30	 */
31	class SyncOutdoorFabricProducts extends Command
32	{
33	    protected $signature = 'app:sync-outdoor-fabric-products';
34	
35	    protected $description = 'Associa ogni tessuto Outdoor a ogni prodotto Outdoor (nessuna matrice: relazione totale)';
36	
37	    public function handle(): int
38	    {
39	        $fabricIds = Fabric::query()
40	            ->whereHas('category', fn ($q) => $q->whereHas(
41	                'category1',
42	                fn ($q2) => $q2->where('slug', 'outdoor'),
43	            ))
44	            ->pluck('id')
45	            ->all();
46	
47	        $products = Product::query()
48	            ->whereHas('category2.category1', fn ($q) => $q->where('slug', 'outdoor'))
49	            ->get(['id']);
50	
51	        if ($fabricIds === []) {
52	            $this->error('Nessun tessuto Outdoor trovato: lanciare prima app:import-fabrics.');
53	
54	            return self::FAILURE;
55	        }
56	
57	        if ($products->isEmpty()) {
58	            $this->error('Nessun prodotto Outdoor trovato in catalogo.');
59	
60	            return self::FAILURE;
61	        }
62	
63	        foreach ($products as $product) {
64	            $product->fabrics()->sync($fabricIds);
65	        }
66	
67	        $this->info('Relazione tessuto ↔ prodotto Outdoor completata.');
68	        $this->table(
69	            ['Metrica', 'Valore'],
70	            [
71	                ['tessuti outdoor', count($fabricIds)],
72	                ['prodotti outdoor', $products->count()],
73	                ['associazioni', count($fabricIds) * $products->count()],
74	            ],
75	        );
76	
77	        return self::SUCCESS;
78	    }
79	}
